<?php

declare(strict_types=1);namespace Atlas\Platform\Workflows\Admin;use Atlas\Platform\Core\Logging\Logger;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;use Atlas\Platform\Workflows\Authoring\WorkflowDraftService;use Atlas\Platform\Workflows\Catalog\WorkflowCatalogRepository;use Atlas\Platform\Workflows\Services\WorkflowReader;use Throwable;
final class WorkflowsAdminPage{private string$hook='';public function __construct(private WorkflowCatalogRepository$catalog,private WorkflowDraftService$drafts,private WorkflowReader$reader,private CurrentOrganizationResolver$organizations,private Logger$logger){}public function register():void{$this->hook=(string)add_submenu_page('atlas',__('Workflows','atlas-platform'),__('Workflows','atlas-platform'),'atlas_access','atlas-workflows',[$this,'render']);add_submenu_page(null,__('Atlas Workflow','atlas-platform'),__('Atlas Workflow','atlas-platform'),'atlas_access','atlas-workflow',[$this,'renderDetail']);}public function enqueue(string$hook):void{if($hook===$this->hook||str_contains($hook,'atlas-workflow')){wp_enqueue_style('atlas-preview',ATLAS_PLATFORM_URL.'assets/css/atlas-preview.css',[],ATLAS_PLATFORM_VERSION);}}public function create():void{if(!current_user_can('atlas_manage_workflows')){wp_die(esc_html__('You are not allowed to manage workflows.','atlas-platform'),'', ['response'=>403]);}check_admin_referer('atlas_create_workflow');$lines=preg_split('/\R/',sanitize_textarea_field(wp_unslash((string)($_POST['steps']??''))))?:[];$steps=[];foreach($lines as$line){if(trim($line)===''){continue;}$parts=array_map('trim',explode('|',$line,4));$steps[]=['title'=>$parts[0]??'','instruction'=>$parts[1]??'','requirement'=>$parts[2]??'','warning'=>$parts[3]??''];}$organization=$this->organizations->resolveForUser(get_current_user_id());$input=['scope'=>sanitize_key(wp_unslash((string)($_POST['scope']??'organization'))),'slug'=>sanitize_title(wp_unslash((string)($_POST['slug']??''))),'title'=>sanitize_text_field(wp_unslash((string)($_POST['title']??''))),'summary'=>sanitize_textarea_field(wp_unslash((string)($_POST['summary']??''))),'source_resource_version_id'=>sanitize_text_field(wp_unslash((string)($_POST['source_resource_version_id']??''))),'steps'=>$steps];try{$result=$this->drafts->create(sanitize_text_field(wp_unslash((string)($_POST['idempotency_key']??''))),$input,$organization?->id??'',get_current_user_id(),current_user_can('atlas_manage_atlas'));$url=add_query_arg(['page'=>'atlas-workflows','atlas_notice'=>$result['replayed']?'restored':'created','version_id'=>$result['workflow_version_id']],admin_url('admin.php'));}catch(Throwable$failure){$this->logger->log('error','workflows.admin_draft_failed','Workflow draft creation from administration failed.',[],'workflows',$failure);$url=add_query_arg(['page'=>'atlas-workflows','atlas_notice'=>'failed'],admin_url('admin.php'));}wp_safe_redirect($url);exit;}public function render():void{if(!current_user_can('atlas_access')){wp_die(esc_html__('You are not allowed to access Atlas workflows.','atlas-platform'),'', ['response'=>403]);}$organization=$this->organizations->resolveForUser(get_current_user_id());$workflows=$this->catalog->publishedForContext($organization?->id);$notice=sanitize_key(wp_unslash((string)($_GET['atlas_notice']??'')));$versionId=sanitize_text_field(wp_unslash((string)($_GET['version_id']??'')));require ATLAS_PLATFORM_DIR.'templates/workflows/index.php';}public function renderDetail():void{if(!current_user_can('atlas_access')){wp_die(esc_html__('You are not allowed to access this workflow.','atlas-platform'),'', ['response'=>403]);}$organization=$this->organizations->resolveForUser(get_current_user_id());$id=strtolower(sanitize_text_field(wp_unslash((string)($_GET['id']??''))));$workflow=$this->reader->find($id,$organization?->id);if($workflow===null){wp_die(esc_html__('The workflow was not found or is not accessible.','atlas-platform'),'', ['response'=>404]);}require ATLAS_PLATFORM_DIR.'templates/workflows/detail.php';}}
